import { useState } from 'react';
import { ChevronRight,ArrowLeft, Car, Home, Smartphone, Briefcase, ShoppingCart, Sofa, Shirt, Dog, Bike, ShoppingBag, User } from 'lucide-react';
import { Link } from 'react-router-dom';

const categories = [
  { name: "Vehicles", icon: <Car className="w-6 h-6 text-red-500" />, subcategories: ["Cars for Sale", "Cars for Rent", "Tyres, Batteries, Oils, & Accessories", "Car Spare Parts", "Motorcycles & Accessories", "Boats - Watercraft", "Heavy Trucks, Buses & Other Vehicles"] },
  { name: "Properties", icon: "🏠", subcategories: [] },
  { name: "Mobiles & Tablets", icon: "📱", subcategories: [] },
  { name: "Jobs", icon: "💼", subcategories: [] },
  { name: "Electronics & Appliances", icon: "📺", subcategories: [] },
  { name: "Furniture & Decor", icon: "🛋️", subcategories: [] },
  { name: "Fashion & Beauty", icon: "💄", subcategories: [] },
  { name: "Pets", icon: "🐾", subcategories: [] },
  { name: "Kids & Babies", icon: "🍼", subcategories: [] },
  { name: "Hobbies", icon: "🎨", subcategories: [] },
  { name: "Businesses & Industrial", icon: "🏭", subcategories: [] },
  { name: "Services", icon: "🧰", subcategories: [] },
];

export default function PostAdPage() {
  const [selectedCategory, setSelectedCategory] = useState(null);

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow py-4 flex items-center justify-between px-4">
        {/* Back Arrow */}
        <Link
          to="/"
          className="flex items-center space-x-2 text-gray-700"
          aria-label="Go back"
        >
          <ArrowLeft className="w-6 h-6" />
          <span className="text-sm">Back</span>
        </Link>

        {/* Logo */}
        <Link to="/">
          <img src="/k1.jpeg" alt="Logo" className="w-[100px] h-auto" />
        </Link>
      </header>

      {/* Main Content */}
      <main className="container mx-auto px-4 py-6">
        <h1 className="text-center text-xl font-semibold mb-6">POST YOUR AD</h1>
        <div className="grid grid-cols-12 gap-4">
          {/* Categories List */}
          <div className="col-span-12 md:col-span-5 bg-white shadow-md rounded-md">
            <h2 className="text-gray-600 font-medium px-4 py-3 border-b">Choose a category</h2>
            <ul>
              {categories.map((category) => (
                <li
                  key={category.name}
                  className={`flex items-center justify-between px-4 py-3 cursor-pointer ${
                    selectedCategory === category.name ? "bg-gray-100" : "hover:bg-gray-50"
                  }`}
                  onClick={() => setSelectedCategory(category.name)}
                >
                  <span className="flex items-center space-x-3">
                    <span className="text-xl">{category.icon}</span>
                    <span>{category.name}</span>
                  </span>
                  <ChevronRight className="text-gray-400" />
                </li>
              ))}
            </ul>
          </div>

          {/* Subcategories List */}
          <div className="col-span-12 md:col-span-7 bg-white shadow-md rounded-md">
            <h2 className="text-gray-600 font-medium px-4 py-3 border-b">
              {selectedCategory || "Select a category"}
            </h2>
            <ul>
              {categories
                .find((category) => category.name === selectedCategory)?.subcategories.map((subcategory) => (
                  <li
                    key={subcategory}
                    className="px-4 py-3 hover:bg-gray-50 cursor-pointer"
                  >
                    {subcategory}
                  </li>
                ))}
            </ul>
          </div>
        </div>
      </main>
    </div>
  );
}
